    nums.sort_unstable();

    let [x, y, z] = nums;

    // If all are already equal
    if x == y && y == z {
        return 0;
    }

    // Try to reach a common target value
    // Since operations only increase numbers, the target must be >= z (largest)
    // We can try targets from z up to some reasonable limit (e.g., z + 4)
    // because differences are small and operations increase by at most 2 per step.

    let mut min_ops = i8::MAX;

    // Upper bound: we won't need to go beyond z + 4 because:
    // - Each operation increases sum by at most 2.
    // - To align three numbers, worst case we might overshoot a bit.
    // - Given max input 50, i8 is safe for calculations here.
    for target in z..=z + 4 {
        let mut ops = 0;
        let mut remaining = [target - x, target - y, target - z];

        // All remainders must be non-negative
        if remaining.iter().any(|&r| r < 0) {
            continue;
        }

        // Pair as many +1/+1 operations as possible
        // Sort to pair smallest remainders first
        remaining.sort_unstable();

        // Use +1/+1 on two numbers while possible
        while remaining[1] > 0 && remaining[2] > 0 {
            remaining[1] -= 1;
            remaining[2] -= 1;
            ops += 1;
            remaining.sort_unstable();
        }

        // Remaining increases must be done with +2 operations
        ops += remaining[0] / 2 + remaining[1] / 2 + remaining[2] / 2;
        // Handle odd remainders (if any left after pairing)
        // Odd remainder means we need an extra +2 operation for that number
        // because +1/+1 operations are exhausted.
        ops += remaining[0] % 2 + remaining[1] % 2 + remaining[2] % 2;

        min_ops = min_ops.min(ops);
    }

